import os, re, time

def load_demos():
    rlm_state_dir = '/home/USER/runs/paper/qwen-hpl-u1-turns/frozen/held-out-4/play/users/u050/system/state/sessions/01a19f0a-1243-7628-a7ae-3e356f5c943e.jsonl'

    if not os.path.exists(rlm_state_dir):
        return {}

    with open(rlm_state_dir) as f:
        content = f.read()

    G = {}

    # Try to find Demo pair input/output patterns
    demo_pattern = r'(Demo pair \d+ (?:input|output)|Test input)\((\d+)x(\d+)\):\n((?:\d+\s+\d+\s+.*?\n)+)'

    for m in re.finditer(demo_pattern, content):
        k, h, w = m[1], int(m[2]), int(m[3])
        all_rows = [r.split() for r in m.group(4).split('\n') if r.strip()]
        if k not in G:
            # Verify all rows have correct width
            valid = all(len(r) == w and all(x.isdigit() for x in r) for r in all_rows[:h])
            if valid:
                G[k] = [[int(x) for x in r] for r in all_rows[:h]]

    return G

G = load_demos()
